from pathlib import Path
from typing import Any


def parse_benchmark_csv(csv_path: Path | str) -> list[dict[str, Any]]:
    """Loads and validates a benchmark CSV report generated by LatencyProfiler."""
    path = Path(csv_path)
    if not path.is_file():
        raise FileNotFoundError(f"Benchmark CSV file not found: {path}")

    records: list[dict[str, Any]] = []
    with path.open(mode="r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            if not row or not row.get("turn_id"):
                continue
            records.append({
                "turn_id": int(row["turn_id"]),
                "request_id": row["request_id"].strip(),
                "suspect_id": row["suspect_id"].strip(),
                "prompt_tokens": int(row["prompt_tokens"]),
                "completion_tokens": int(row["completion_tokens"]),
                "ttft_ms": round(float(row["ttft_ms"]), 2),
                "generation_time_ms": round(float(row["generation_time_ms"]), 2),
                "tokens_per_sec": round(float(row["tokens_per_sec"]), 2),
                "sla_passed": str(row["sla_passed"]).strip().lower() in ("true", "1", "yes"),
            })

    if not records:
        raise ValueError(f"No valid benchmark records found in: {path}")

    return records


def _percentile(values: list[float], p: float) -> float:
    """Calculates the p-th percentile of a list of floats (0 <= p <= 100)."""
    if not values:
        return 0.0
    sorted_vals = sorted(values)
    k = (len(sorted_vals) - 1) * (p / 100.0)
    f = math.floor(k)
    c = math.ceil(k)
    if f == c:
        return sorted_vals[int(k)]
    d0 = sorted_vals[int(f)] * (c - k)
    d1 = sorted_vals[int(c)] * (k - f)
    return d0 + d1


def compute_summary_metrics(records: list[dict[str, Any]], sla_threshold_ms: float = 800.0) -> dict[str, Any]:
    """Computes comprehensive telemetry statistics across all recorded turns."""
    total_turns = len(records)
    if total_turns == 0:
        raise ValueError("Cannot compute metrics from empty records.")

    ttfts = [r["ttft_ms"] for r in records]
    durations = [r["generation_time_ms"] for r in records]
    tps = [r["tokens_per_sec"] for r in records]
    prompt_tokens = [r["prompt_tokens"] for r in records]
    completion_tokens = [r["completion_tokens"] for r in records]
    sla_passed_count = sum(1 for r in records if r["sla_passed"])

    return {
        "total_turns": total_turns,
        "sla_threshold_ms": sla_threshold_ms,
        "sla_passed_count": sla_passed_count,
        "sla_pass_rate": round((sla_passed_count / total_turns) * 100.0, 2),
        "ttft_ms": {
            "min": round(min(ttfts), 2),
            "mean": round(sum(ttfts) / total_turns, 2),
            "median": round(_percentile(ttfts, 50), 2),
            "p90": round(_percentile(ttfts, 90), 2),
            "p95": round(_percentile(ttfts, 95), 2),
            "p99": round(_percentile(ttfts, 99), 2),
            "max": round(max(ttfts), 2),
        },
        "generation_time_ms": {
            "min": round(min(durations), 2),
            "mean": round(sum(durations) / total_turns, 2),
            "median": round(_percentile(durations, 50), 2),
            "p95": round(_percentile(durations, 95), 2),
            "max": round(max(durations), 2),
        },
        "tokens_per_sec": {
            "min": round(min(tps), 2),
            "mean": round(sum(tps) / total_turns, 2),
            "median": round(_percentile(tps, 50), 2),
            "max": round(max(tps), 2),
        },
        "tokens": {
            "total_completion": sum(completion_tokens),
            "mean_completion": round(sum(completion_tokens) / total_turns, 1),
            "prompt_tokens_per_turn": prompt_tokens[0] if prompt_tokens else 0,
        },
    }


def print_cli_summary(metrics: dict[str, Any], model_name: str = "qwen2.5:3b") -> None:
    """Prints a styled CLI summary card to standard output."""
    ttft = metrics["ttft_ms"]
    gen = metrics["generation_time_ms"]
    tps = metrics["tokens_per_sec"]
    pass_rate = metrics["sla_pass_rate"]

    status = "PASSED" if pass_rate >= 95.0 else "FAILED"
    color_code = "\033[92m" if status == "PASSED" else "\033[91m"
    reset_code = "\033[0m"

    print("\n" + "=" * 70)
    print(" RED THREAD AI DETECTIVE -- LLM INTERROGATION BENCHMARK SUMMARY")
    print("=" * 70)
    print(f" Target Model        : {model_name} (Q4_K_M, 3.09B params)")
    print(f" Target SLA          : TTFT < {metrics['sla_threshold_ms']} ms")
    print(f" Sample Count        : {metrics['total_turns']} Streaming Turns")
    print(f" SLA Compliance      : {color_code}{metrics['sla_passed_count']}/{metrics['total_turns']} ({pass_rate}%) [{status}]{reset_code}")
    print("-" * 70)
    print(" METRIC (TTFT)       : MIN       MEAN      P95       MAX (Cold Start)")
    print(f" Latency (ms)        : {ttft['min']:<9.2f} {ttft['mean']:<9.2f} {ttft['p95']:<9.2f} {ttft['max']:<9.2f}")
    print("-" * 70)
    print(" METRIC (GENERATION) : MIN (ms)  MEAN (ms) P95 (ms)  MEAN SPEED")
    print(f" Duration & Speed    : {gen['min']:<9.2f} {gen['mean']:<9.2f} {gen['p95']:<9.2f} {tps['mean']:<6.2f} tok/s")
    print("=" * 70 + "\n")


